def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser()
    parser.add_argument(
        "--scenario",
        default="recent64-plus-failure",
        choices=tuple(SCENARIOS),
        help="Which embedded chat window to replay.",
    )
    parser.add_argument(
        "--cudagraph-mode",
        default=CUDAGRAPH_MODE,
        choices=("FULL_AND_PIECEWISE", "PIECEWISE", "FULL", "FULL_DECODE_ONLY", "NONE"),
        help="vLLM CompilationConfig.cudagraph_mode.",
    )
    return parser.parse_args()


def load_payload() -> dict[str, Any]:
    raw = gzip.decompress(base64.b64decode(_PAYLOAD_B64_GZ.encode("ascii")))
    return json.loads(raw.decode("utf-8"))


def select_requests(payload: dict[str, Any], scenario: str) -> list[dict[str, Any]]:
    recent = sorted(
        payload["recent_requests"], key=lambda row: float(row.get("created_at") or 0.0)
    )
    failure = payload["failure"]
    if scenario == "failure-only":
        rows = [failure]
    elif scenario == "last8-plus-failure":
        rows = recent[-8:] + [failure]
    elif scenario == "last32-plus-failure":
        rows = recent[-32:] + [failure]
    elif scenario == "recent64-plus-failure":
        rows = recent + [failure]
    else:
        raise ValueError(scenario)

    deduped: list[dict[str, Any]] = []
    seen: set[str] = set()
    for row in rows:
        request_id = str(row.get("request_id"))
        if request_id in seen:
            continue
        seen.add(request_id)
        deduped.append(row)
    return deduped


def make_sampling_params(body: dict[str, Any]) -> SamplingParams:
    requested_max = (
        body.get("max_completion_tokens")
        or body.get("max_tokens")
        or REPLAY_MAX_TOKENS_CAP
    )
    return SamplingParams(
        n=int(body.get("n", 1)),
        temperature=float(body.get("temperature", 1.0)),
        top_p=float(body.get("top_p", 1.0)),
        top_k=int(body.get("top_k", -1)),
        min_p=float(body.get("min_p", 0.0)),
        stop=body.get("stop"),
        stop_token_ids=body.get("stop_token_ids"),
        max_tokens=min(int(requested_max), REPLAY_MAX_TOKENS_CAP),
        min_tokens=int(body.get("min_tokens", 0)),
        logprobs=0 if body.get("logprobs") else None,
        prompt_logprobs=None,
        detokenize=True,
        skip_special_tokens=bool(body.get("skip_special_tokens", True)),
    )


def logprob_value(entry: Any, sampled_token_id: int | None) -> float | None:
    if entry is None:
        return None
    if isinstance(entry, (int, float)):
        return float(entry)
    if isinstance(entry, dict):
        value = None
        if sampled_token_id is not None:
            value = entry.get(sampled_token_id) or entry.get(str(sampled_token_id))
        if value is None and entry:
            value = next(iter(entry.values()))
        return logprob_value(value, sampled_token_id)
    if hasattr(entry, "logprob"):
        return float(entry.logprob)
    return None


def first_nonfinite(output: Any) -> tuple[int, int, int | None, float] | None:
    for choice_index, completion in enumerate(output.outputs):
        token_ids = list(completion.token_ids)
        for offset, entry in enumerate(completion.logprobs or []):
            sampled_token_id = token_ids[offset] if offset < len(token_ids) else None
            value = logprob_value(entry, sampled_token_id)
            if value is not None and not math.isfinite(value):
                return choice_index, offset, sampled_token_id, value
    return None


def max_repeated_token_run(token_ids: list[int], token_id: int = 0) -> tuple[int, int]:
    best_len = 0
    best_start = -1
    cur_len = 0
    cur_start = 0
    for index, sampled in enumerate(token_ids):
        if sampled == token_id:
            if cur_len == 0:
                cur_start = index
            cur_len += 1
            if cur_len > best_len:
                best_len = cur_len
                best_start = cur_start
        else:
            cur_len = 0
    return best_start, best_len


def describe_output(row: dict[str, Any], output: Any) -> tuple[bool, str]:
    completion = output.outputs[0] if output.outputs else None
    if completion is None:
        return False, f"REQUEST_EMPTY request_id={row.get('request_id')}"
    token_ids = list(completion.token_ids)
    token0_start, token0_len = max_repeated_token_run(token_ids, token_id=0)
    bad = first_nonfinite(output)
    prefix = (
        f"request_id={row.get('request_id')} messages={len(row['body'].get('messages') or [])} "
        f"finish={completion.finish_reason} completion_tokens={len(token_ids)} "
        f"repeated_token0={token0_len}@{token0_start}"
    )
    if bad is None:
        return False, f"REQUEST_OK {prefix}"
    choice_index, offset, token_id, value = bad
    window_start = max(0, offset - 16)
    window_end = min(len(token_ids), offset + 17)
    return True, (
        f"REQUEST_NONFINITE {prefix} choice={choice_index} offset={offset} "
        f"token_id={token_id} value={value} "
        f"token_window={token_ids[window_start:window_end]}"
    )


def main() -> int:
    args = parse_args()
    payload = load_payload()
    rows = select_requests(payload, args.scenario)
    bodies = [row["body"] for row in rows]
    tools = bodies[-1].get("tools")
    same_tools = all(body.get("tools") == tools for body in bodies)
    if not same_tools:
        raise RuntimeError(
            "Selected requests do not share the same tool schema; split the scenario."
        )

    print(
        "REPRO_SETTING "
        f"scenario={args.scenario} source={payload['source_file']} "
        f"selected_count={len(rows)} failure_request_id={FAILURE_REQUEST_ID} "
        f"failure_present={any(row.get('request_id') == FAILURE_REQUEST_ID for row in rows)} "
        f"captured_failure_prompt_tokens={payload.get('failure_prompt_token_count')} "
        f"captured_failure_completion_tokens={payload.get('failure_completion_token_count')} "
        f"captured_nonfinite_paths={len(payload.get('failure_nonfinite_paths') or [])} "
        f"max_tokens_cap={REPLAY_MAX_TOKENS_CAP}"
    )
    print(
        "ENGINE_SETTING "
        f"model={MODEL} tp={TENSOR_PARALLEL_SIZE} max_model_len={MAX_MODEL_LEN} "
        f"max_num_seqs={MAX_NUM_SEQS} gpu_memory_utilization={GPU_MEMORY_UTILIZATION} "
        f"dtype={DTYPE} cudagraph_mode={args.cudagraph_mode} "
        f"enforce_eager={ENFORCE_EAGER} prefix_caching={ENABLE_PREFIX_CACHING}"
    )
    for index, row in enumerate(rows):
        body = row["body"]
        print(
            "INPUT_ROW "
            f"index={index} request_id={row.get('request_id')} created_at={row.get('created_at')} "
            f"messages={len(body.get('messages') or [])} max_completion_tokens={body.get('max_completion_tokens')} "
            f"temperature={body.get('temperature')} top_p={body.get('top_p')}"
        )

    llm = LLM(
        model=MODEL,
        tensor_parallel_size=TENSOR_PARALLEL_SIZE,
        dtype=DTYPE,
        max_model_len=MAX_MODEL_LEN,
        max_num_seqs=MAX_NUM_SEQS,
        gpu_memory_utilization=GPU_MEMORY_UTILIZATION,
        seed=SEED,
        enforce_eager=ENFORCE_EAGER,
        enable_chunked_prefill=ENABLE_CHUNKED_PREFILL,
        enable_prefix_caching=ENABLE_PREFIX_CACHING,
        logprobs_mode=LOGPROBS_MODE,
        compilation_config={"cudagraph_mode": args.cudagraph_mode},
    )

    conversations = [body["messages"] for body in bodies]
    sampling_params = [make_sampling_params(body) for body in bodies]

    start = time.monotonic()
    outputs = llm.chat(
        conversations,
        sampling_params=sampling_params,
        use_tqdm=False,
        add_generation_prompt=bool(bodies[-1].get("add_generation_prompt", True)),
        continue_final_message=bool(bodies[-1].get("continue_final_message", False)),
        tools=tools,
    )
    elapsed = time.monotonic() - start

    nonfinite_ids: list[str] = []
    max_token0_run = 0
    for row, output in zip(rows, outputs, strict=True):
        completion = output.outputs[0] if output.outputs else None
        if completion is not None:
            _, token0_len = max_repeated_token_run(
                list(completion.token_ids), token_id=0
            )
            max_token0_run = max(max_token0_run, token0_len)
        is_nonfinite, line = describe_output(row, output)
        print(line)
        if is_nonfinite:
            nonfinite_ids.append(str(row.get("request_id")))

    print(
        "SUMMARY "
        f"elapsed_seconds={elapsed:.1f} selected_count={len(rows)} "
        f"nonfinite_count={len(nonfinite_ids)} nonfinite_ids={nonfinite_ids} "
        f"max_repeated_token0={max_token0_run}"
    )
    if nonfinite_ids:
        print("RESULT failed: observed non-finite generated logprob")
        return 2
    print("RESULT passed: no non-finite generated logprobs observed")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
